/* Evolvlings: English text for the era 4 path conversations (parallel to events-era4.js). */
window.EVEVENTS_EN = window.EVEVENTS_EN || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Delivery 1: root metal, the strike, the stone hands and the Bell ==================== */

  add("crater", {
    "e4-fogarin": { who: { fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["At the bottom of the Crater, where a stone slope used to be, there is now a wide pit with iron stairs. Down below, something red glows and never goes out. Up top, a very old man in the Master's apron waits for you beside an enormous mould.",
                 "Caretaker. Come, come. Look at this. It's the Bell's mould. When we cast it, the Root will sleep without anyone singing to it. Not you, not the Houses, not anyone who charges for the lullaby.",
                 "All my life I saw Fire bought. By the Houses, by water, by whoever had more. With this, Fire gives the Glade something nobody can buy. A bronze sleep for the Root."],
           opts: ["“Where does the metal come from?”", "“Who's going to ring the Bell?”", "“I've seen your workers' hands.”", "“The Houses sold their forges over the Tides' version.”", "“Help me understand how it works.”"] },
      metal: { say: ["From below. From very far below. It's hot and never cools, even if you put it in snow. The old folk said it was the Root's blood. The old folk said many things.",
                     "I say it's metal. And that with it you make things that couldn't be made before."] },
      quien: { say: ["That's the question. The Houses are already buying turns. As if the Bell were a furnace you could rent.",
                     "I want nobody who pays to ring it. But then I don't know who. That's why I'm asking you too."] },
      manos: { say: ["Yes. I've seen them.",
                     "He looks at his own hands. His nails have a grey line along the edge, fine, as if painted with ash.",
                     "The deep furnaces are tiring. Hands get hard with work. It was always like that in the Guild.",
                     "He doesn't look at you as he says it."] },
      mareas: { say: ["I bought them. Cheap. Ola told me not to. I did it anyway: if the Guild didn't buy them, someone else would.",
                      "Now I have more furnaces than anyone in the history of the Glade. And every day someone reminds me they were someone else's."] },
      ayudar: { say: ["Fogarín shows you the plans, the furnaces, the channel the metal will run along. He talks fast, with his hands, like the apprentice he was sixty years ago.",
                      "The bell rings once, and the note goes down to the bottom, to the Root. No eight verses to sing. No nine peoples to bring together. One note and that's it.",
                      "He says it as if that were the good part. You realise that, for him, it is."] },
    } },

    "e4-huelga": { who: { escoria: "Escoria, worker", cobre: "Cobre, of the Houses" }, nodes: {
      a: { say: ["At the entrance to the deep furnaces, a hundred workers sit on the ground with their arms crossed. In front of them, a woman with a soot-covered face shouts louder than everyone.",
                 "Not one more shovel! Not one more ingot! Let them go down to the deep furnaces, and see how long before they can't close their fist.",
                 "Behind you, a well-dressed young man takes you by the elbow. He wears a House crest on his chest, worn.",
                 "Caretaker. My name is Cobre. My House paid the Guild for the Bell, in advance. If the strike goes on, there's no Bell, and my House goes under. Take this to the worker: a purse for everyone who goes back to work."],
           opts: ["“Escoria, what exactly are you asking for?”", "Back the strike and sit with the workers", "Carry Cobre's message", "Mediate between the workers and the Guild"] },
      piden: { say: ["That the deep furnaces close. That root metal be dug only in short shifts. And that the Guild say out loud what's happening to our hands.",
                     "We're not asking for money. We've been given money. Money doesn't open fingers."] },
      apoyar: { say: ["You sit on the ground among the workers. After a while, your creature lies down beside you. The workers look at it, and one scratches its head with a hard, grey hand.",
                      "The Caretaker is with us. The Caretaker is with us!",
                      "Word spreads. That night the deep furnaces close. Fogarín doesn't come down to talk. Cobre leaves without saying goodbye.",
                      "The Guild won't forget this. Nor will the Houses. But the fingers that don't turn to stone this week are ours."] },
      recado: { say: ["You take the purse to Escoria. She opens it, looks inside and throws it at her feet.",
                      "A purse. For my hands.",
                      "But behind her, a young worker bends down and picks it up. Then another. The next day, half go back to the deep furnaces. Escoria stays alone at the entrance, shouting, louder than ever.",
                      "Thank you. My House doesn't forget those who help it. Nor those who don't."] },
      mediar: { say: ["You go up to talk to Fogarín. You go down to talk to Escoria. You go up again. It takes three days.",
                      "In the end there's a deal: one-hour shifts in the deep furnaces, and a worker who checks everyone's hands on the way out. Nobody's happy. Everybody signs.",
                      "This is little. But I signed it. If tomorrow I see one more hand of stone, I tear up the paper.",
                      "The Bell will be a year late. My House doesn't have a year. But fine. Thank you for not choosing."] },
    } },

    "e4-manos": { who: { yunque: "Yunque, smith" }, nodes: {
      a: { say: ["At the last furnace, the deepest, a smith as broad as a door hammers a red ingot. He wears an amulet with the face of a nameless statue. He strikes with one hand. The other rests on the anvil, still.",
                 "I can't move it. For a moon now. It doesn't hurt. It just weighs.",
                 "It's the Nameless Smith, the one of the third statue. He forged the Glade's first tools. If the same happens to me as to him, it's because I'm doing what he did. It's an honour."],
           opts: ["“Do you know how the Smith ended?”", "Tell all the workers about the statue", "Say nothing", "Tell only Yunque"] },
      termino: { say: ["He stayed in the Heart. Forever. As a statue. That's what the rites say.",
                       "They don't say why. I think because he'd finished his work. I want to finish mine too."] },
      contar: { say: ["You gather the shift's workers at the furnace mouth. You tell them about the third statue: the slag stuck to its base, just like on their hands. The smith who drew metal from below and ended up as stone.",
                      "Silence. Then a murmur. One worker looks at his nails. Another puts his shovel down and doesn't pick it up again.",
                      "You took away the honour. Now it's only fear.",
                      "The next day, half the workers don't go down. The deep furnaces run at half. Yunque goes down anyway, with his still hand."] },
      callar: { say: ["You say nothing. Yunque keeps hammering. The ingot goes black, then red again, as if it were breathing.",
                      "You know something. It shows. Well. Everyone carries their own.",
                      "The deep furnaces keep working at full fire. That night, in the Heart, someone leaves a candle at the foot of the third statue."] },
      yunque: { say: ["You wait for the others to leave. You tell Yunque, only him, about the statue and the slag.",
                      "Then it wasn't an honour. It was a price.",
                      "He stays a long while looking at his grey hand on the anvil.",
                      "I'll finish the Bell anyway. But I'll be the last to go down that deep. I'll send the others up. And I won't tell them why. If I tell them, they'll leave. And if they leave, the Bell doesn't get finished."] },
    } },

    "e4-ascuas": { who: { tizon: "Master Tizón" }, nodes: {
      a: { say: ["In an old house at the edge of the Crater, an old man counts coins on the table, each pile twice. He is over a hundred. His eyes are two tiny embers.",
                 "You. I remember you. From before everything. When the Night of Embers was a feast, and the furnaces went out one night a year so Fire would remember it also knows how not to burn.",
                 "It hasn't been held for forty years. The Guild says it's a lost night of work. I say it's the only night Fire doesn't drink. Nobody remembers what it was like any more."],
           opts: ["“What was the Night of Embers like?”", "Bring back the Night of Embers this year", "“Leave it forgotten. It doesn't belong to these times.”"] },
      como: { say: ["Every furnace went out at sunset. Every one. The song of Fire was sung with cold hands. And in the morning only one was lit, with an old ember, and from that one the others were lit.",
                    "It was to remember that Fire begins in a single ember. That it belongs to nobody. I've forgotten the song's words. I remember the tune."] },
      revivir: { say: ["You go from furnace to furnace with Tizón, who walks with two canes. He talks to the masters. You talk to the workers. Some laugh. Many don't.",
                       "At sunset on the shortest day, the furnaces go out. Not all: the deep ones keep burning, because root metal won't let itself be put out. But the others do. The Crater goes dark for the first time in forty years.",
                       "Someone hums the tune. Others join in. Nobody knows the words. Escoria, in the dark, makes some up.",
                       "It wasn't like that. But it's close. In the morning I'll light the first one. With an old ember. I've kept one for forty years."] },
      olvidar: { say: ["Forgotten. Yes. Like me.",
                       "He goes back to counting the coins. He loses count. He starts again.",
                       "When I die, there'll be nobody left who remembers the tune. Well. Maybe Fire doesn't need to remember anything. Maybe that's why it drinks so much."] },
    } },
  });

  add("aurora", {
    "e4-cobre": { who: { cobre: "Cobre, of the Houses" }, nodes: {
      a: { say: ["In the Meadow square there's an enormous board with squares. Each square is a night of the year. Half already have a House crest painted on. A young man, in a good coat with worn cuffs, paints another.",
                 "Bell turns. Whoever holds the night decides whether the Root sleeps that night or not. If it sleeps, nothing moves under the Meadow. If not, you can dig.",
                 "My House bought eight nights with the last of what it had. If the Bell isn't finished, my House is finished. So, you see, Caretaker: I'm for the Bell."],
           opts: ["“And why would they want the Root not to sleep?”", "“The Court didn't forget the Chronicle, did it?”", "“Let your House buy a night for the Quarter.”", "“Selling nights of sleep is selling the Root.”"] },
      para: { say: ["To dig, of course. When the Root sleeps, you can't draw metal from below: the ground closes. When it's awake, it opens. That's how it is.",
                    "Don't look at me like that. My great-grandmother sold light. My grandmother, candles. My mother, nothing. I sell nights. It's what there is."] },
      corte: { say: ["No. They buy nights too, under another name. On the nights they hold, the Root doesn't sleep, and the ground opens beneath the Meadow.",
                     "Fifty years of the Official Chronicle and the Court collects on it one night at a time."] },
      barrio: { say: ["A night for the Quarter? For free?",
                      "He looks at the board. At the brush. He paints a square, the longest night of the year, with a crooked drawing of a door with no lantern.",
                      "Let them decide it. One night. My mother would die all over again if she saw it. But the Houses can't go to the Heart asking without having given anything."] },
      vender: { say: ["Everything gets sold, Caretaker. Water got sold. Light got sold. If I don't sell it, someone else will, and someone else keeps the House.",
                      "He finishes painting the crest. His hand shakes a little."] },
    } },

    "e4-chispa": { who: { chispa: "Chispa", tizon: "Master Tizón" }, nodes: {
      a: { say: ["On the road from the Meadow to the Crater, a skinny girl from the south slope crouches beside an ingot fallen from a cart. She touches it with a fingertip. Pulls back. Touches it again.",
                 "It doesn't burn that much. It burns nice. Like when you sit really close to the fire in winter.",
                 "My name's Chispa. I want to learn to forge. They won't let me into the Guild because I'm from the south slope and I don't have a furnace surname. But I know my hands are good for it."],
           opts: ["“Look at your finger.”", "Take her to Master Tizón", "Give her a hammer and tell her to forge with common iron", "“Don't touch that. Go home.”"] },
      dedo: { say: ["Chispa looks at her fingertip. There's a little grey spot, the size of a lentil, where she touched the ingot.",
                    "It'll go away. It comes off with water. Right?",
                    "She rubs it on her dress. It doesn't come off."] },
      tizon: { say: ["Tizón looks at her from his chair. He makes her clench a fist, open her hand, hold an empty pair of tongs.",
                     "She has forge hands. A pity she was born in these times. I'll teach her to forge cold. River iron. No metal from below.",
                     "Cold? That's for little kids.",
                     "That's for people who want to have hands when they're old. Learn that first. The other thing, anyone can learn."] },
      martillo: { say: ["You give her a small hammer from your belt. Chispa holds it with both hands, like a treasure.",
                        "Common iron. Fine. I'll still make something with this. Something nobody's made.",
                        "She runs off towards the slope. From the fallen ingot on the road rises a thin smoke that smells of scorched earth."] },
      casa: { say: ["You too. Everyone tells me that.",
                    "She leaves. But first, when she thinks you're not looking, she touches the ingot again with her fingertip."] },
    } },
  });

  add("forest", {
    "e4-tala": { who: { hacha: "Hacha, woodcutter" }, nodes: {
      a: { say: ["In the Deep Wood there's a sound that was never heard before: axes, many of them, all day long. Where a three-hundred-year-old oak stood there's a stump as wide as a table, dripping resin as if it were weeping.",
                 "The Guild pays three times what the Council pays for looking after the trees. The deep furnaces need wood to heat the cold metal before mixing it with the root metal.",
                 "My grandmother looked after these trees. I cut them down. My daughter will eat this winter. You do the sums."],
           opts: ["“What does the Council say?”", "“For every tree you cut, plant three.”", "Hide their axes for a night", "Help her carry the wood"] },
      concejo: { say: ["The Council says no. The Council has said no to everything for a hundred years. While they say no, the Guild pays.",
                       "If the Council paid as much for caring as the Guild pays for cutting, there'd be no axes in the Wood. But the Council has no furnaces. It has moss."] },
      plantar: { say: ["Three? And who pays for the saplings?",
                       "She thinks it over with her axe on her shoulder. Then she whistles loudly. The other woodcutters stop cutting.",
                       "Three for every one. We'll pay for it, out of our wages. And we'll bill the Guild for it later, in the Heart, when it's time to talk about who pays for what. Let the Council see the Wood also knows how to care without saying no."] },
      esconder: { say: ["At night you hide the axes in a hollow under the roots of an old tree. In the morning, the woodcutters search the whole clearing for them.",
                        "Hacha finds them at noon. She looks at you from a distance. She says nothing. That afternoon they cut twice as much, to make up for the lost day."] },
      cargar: { say: ["You carry wood with her to the cart. It's heavy, damp, and smells of resin. By the end of the day your arms are covered in scratches.",
                      "Thank you. Nobody from outside helps us. They look at us as if we were the Guild. We're not the Guild. We're the ones the Guild uses."] },
    } },

    "e4-resina": { who: { hacha: "Hacha, woodcutter", escoria: "Escoria, worker", fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["In the clearing of stumps, Escoria sits with her hands sunk to the wrists in a bucket of warm resin. Her eyes are closed. Hacha watches her with her arms crossed.",
                 "It softens. The resin of old trees softens the hands. It doesn't cure them, but it softens them. I can close my fist again.",
                 "Only the old trees' resin. The three-hundred-year-old ones. For one bucket you have to cut one down. And there are four hundred workers with grey hands in the Crater."],
           opts: ["“How many old trees are left?”", "“Cut as many as it takes. Hands first.”", "“Not one more. Find another way.”", "“One bucket per furnace, and the Guild pays.”"] },
      cuantos: { say: ["Two hundred, maybe. There used to be thousands. The furnaces of before took them, and the ones before those.",
                       "Two hundred trees. Four hundred hands. I'm not going to choose which is worth more. That's what the people in charge are for."] },
      cortar: { say: ["That week twenty old trees come down. The resin goes in buckets to the Crater. The workers put their hands in and pull them out soft, pink, and some of them cry.",
                      "Twenty. In a week. My grandmother spent her whole life watching one grow.",
                      "Thank you. I don't care about the Wood. I care about these fingers. But thank you."] },
      ninguno: { say: ["Another way? Which? Tell me and I'll use it.",
                       "You have no answer. Escoria takes her hands out of the bucket. They stiffen again as you watch.",
                       "It's not fair on her. But it's not fair on the trees either. Sometimes nothing's fair, and you have to choose anyway."] },
      gremio: { say: ["You take the proposal to the Guild. Fogarín signs it that same afternoon, without haggling: one bucket of resin per furnace, per moon, paid by the Guild, and three saplings for every tree.",
                      "I'm not doing it to be good. I'm doing it because if the workers can't close their fists, there's no Bell.",
                      "I don't care why. He signed it. That stays."] },
    } },
  });

  add("hollow", {
    "e4-hulla": { who: { hulla: "Hulla, Court charcoal burner" }, nodes: {
      a: { say: ["Behind the Hollow, in a smaller hollow, there are mountains of charcoal as black as holes. A woman in a grey veil, her hands stained, covers them with tarpaulins so they can't be seen from above.",
                 "Shadow charcoal. The wood here, burned slowly underground, makes a charcoal that burns without smoke. The Guild uses it for the deep furnaces, where smoke has nowhere to go.",
                 "We sell it by the back door. If the Houses knew the Court was heating the Bell, they'd stop buying turns. And the Court needs the coins."],
           opts: ["“Why hide it?”", "“Sell it in broad daylight, under the Court's name.”", "“Let the Quarter have charcoal this winter.”", "Tell Cobre"] },
      esconder: { say: ["Because the Court has always done things behind people's backs. It's what it knows how to do. It did it with the sap, with the wells, with the visions.",
                        "And because if it's known, they'll blame us again. For the Bell, for the hands, for whatever happens next. They blamed us once already for a night that belonged to everyone."] },
      luz: { say: ["Under the Court's name? Let everyone see we're part of this?",
                   "She looks at the tarpaulins. At the charcoal. She takes off her veil and folds it.",
                   "All right. If they're going to blame us, let it be for something we really did, and in plain sight. Let it be seen too that the Bell has something of ours. When the Heart calls, the Court will be there."] },
      barrio: { say: ["Hulla sends three carts to the Quarter that same night, with no note, no veil, no crest.",
                      "For the wells. For the Night of Lanterns. For whatever it was. It's not forgiveness. It's charcoal."] },
      cobre: { say: ["Cobre finds out that same afternoon. The next day, the Houses hand back twelve Bell turns. They demand the Guild stop buying charcoal from the Court.",
                     "I knew it would happen. It always does. The Court keeps the charcoal and loses the coins. And the Guild buys the charcoal anyway, cheaper, at another back door."] },
    } },

    "e4-ebano": { who: { ebano: "Ébano, Court archivist", yunque: "Yunque, smith" }, nodes: {
      a: { say: ["In the Court archive, a young archivist with a new veil and clean hands unrolls a parchment so old it crumbles at the edges.",
                 "This was in the oldest box. It's a list of the Glade's first forges. And at the end, crossed out in ink from another age, a name: that of the smith who drew the first metal from below.",
                 "The Nameless Smith had a name. Someone erased it. And the seal that crossed it out belongs to the Ember Guild."],
           opts: ["“Why would the Guild have erased it?”", "“Take it to Yunque. He prays to that man.”", "“Show it in the Heart, to everyone.”", "“Keep it. This isn't the moment.”"] },
      porque: { say: ["I suppose because a smith with a name is a man who died of his work. A smith without a name is a saint.",
                      "Saints get prayed to. The dead of work get paid. The Guild preferred to pray."] },
      yunque: { say: ["You take the parchment to the Crater. Yunque holds it with his good hand. The other hangs, grey, at his side.",
                      "He reads the name under his breath. He doesn't repeat it. He folds it and keeps it in the amulet, behind the nameless face.",
                      "Now I know who I'm praying to. Not a saint. A worker nobody looked after. I'll finish the Bell for him. And afterwards I'll say his name out loud."] },
      corazon: { say: ["Ébano takes the parchment to the Heart and nails it to the base of the third statue, over the slag.",
                       "Guild folk tear it down that same night. The next day there are four copies nailed up. Someone at Court spent the night copying.",
                       "The Court knows how to hide things. This time it knew how to show them. It's the first time I've felt proud of the veil."] },
      guardar: { say: ["You're right. If it comes out now, the Guild will say the Court made up the paper to stop the Bell.",
                       "He rolls it up carefully and puts it in a new box, under lock and key.",
                       "Some day someone will need that name. I hope it isn't too late."] },
    } },
  });

  add("lake", {
    "e4-hierve": { who: { salitre: "Salitre, fisher", fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["On the south shore of the Mirror Lake steam rises from the water as from a pot. White fish float, cooked. A Tides woman gathers them with a net, looking disgusted.",
                 "There are furnaces underneath. The Guild's deep furnaces, dug under the Crater until they got here. The water boils where they are.",
                 "My grandmother sold water. My mother looked after it. I gather cooked fish nobody wants to buy because it smells of metal. The Tides always pay for what others do down below."],
           opts: ["“Does the Guild know this is happening?”", "“Let the Guild pay the Tides for every furnace under the lake.”", "Dive near the steam to see what's there", "Help her gather the fish for the Quarter"] },
      sabe: { say: ["It knows. We sent it a boat full of cooked fish. They sent us a bag of coins and a note: “Thank you for the fish.”",
                    "That's how they are. They pay you to keep quiet, and call it buying."] },
      pagar: { say: ["You go to the Crater with Salitre and a boatload of cooked fish. Fogarín looks at them, one by one, for a long time.",
                     "I grew up among the Tides. Ola taught me to swim. And now I'm boiling their lake.",
                     "He signs a paper: a coin per cooked fish, every week, for as long as there are furnaces underneath. It isn't much. It's something.",
                     "Nobody ever paid us for what they took. The Tides will go to the Heart with this paper. Let it be seen."] },
      bucear: { say: ["You wade into the warm water. The deeper you go, the hotter it gets. Below you see a red light, and walls of carved stone, old, very old.",
                      "You come up before it hurts. Your skin is red as a shrimp.",
                      "Did you see something? You look like you saw something."] },
      barrio: { say: ["You gather the fish in baskets and carry them to the Quarter. They smell of metal, but they're cooked and they're free.",
                      "They eat them anyway. Hunger has no sense of smell. That's what my grandmother used to say."] },
    } },

    "e4-forjahundida": { who: { salitre: "Salitre, fisher", yunque: "Yunque, smith" }, nodes: {
      a: { say: ["The water has dropped again where it boils, and on the south shore a stone structure nobody had seen shows through: an ancient furnace, round, its mouth facing the lake. Inside, still, a red ember.",
                 "It's a forge. Under the water. Older than anything the Guild has.",
                 "On the furnace stone there are handprints. Many, carved, as if someone had pressed their hands to the hot stone to leave the mark. The last prints are stone too: they're stuck to the wall, like grey gloves."],
           opts: ["Touch the stone handprints", "Tell the Guild", "Cover it with mud so the water covers it again", "Bring Yunque"] },
      tocar: { say: ["You touch one of the stone hands stuck to the wall. It's warm, like a real hand.",
                     "For an instant you feel a weight in your fingers, as if they'd gone to sleep. You pull your hand away. The weight goes slowly.",
                     "The colour's gone from your face. What did you feel?",
                     "You can't explain it. Something that stayed here working until it couldn't move any more."] },
      gremio: { say: ["Three Guild masters arrive with torches. They stare at the furnace open-mouthed. One takes out a notebook and starts measuring.",
                      "There. Now they'll want to use it. A forge that never went out. It'll look like a gift to them.",
                      "The next day there's a rope around the furnace and a sign with the Guild's crest."] },
      tapar: { say: ["You pile mud over the furnace mouth until the ember can't be seen. That night the water rises and covers everything again.",
                     "Let it stay down there. What was below, below. My grandmother said that about the lake. We never listened to her."] },
      yunque: { say: ["Yunque comes walking from the Crater, his grey hand hanging. He goes into the sunken furnace. He puts his good hand on one of the stone prints. It fits exactly.",
                      "He worked here. Here. Not in the Crater. The first one didn't forge in the mountain. He forged in the water, so the metal would cool.",
                      "And his hands went anyway. Water and all. So there's no way to work that metal without paying for it."] },
    } },
  });

  add("caves", {
    "e4-galena": { who: { galena: "Galena, miner" }, nodes: {
      a: { say: ["The new tunnels in the Caves aren't cold. You go down and the air gets warm, then hot. A Hondura miner, her helmet dented and her back soaked, pushes a wheelbarrow full of red stones.",
                 "Root metal. The Guild pays by the barrow. The Hondura has never earned so much. My grandfather knocked on walls for the dead. I knock on them for the Guild.",
                 "The trouble is, the deeper you go, the hotter. And sometimes the wall answers. You knock, and the wall knocks back. From the other side."],
           opts: ["“Who knocks from the other side?”", "“Let the Hondura stop digging the hot tunnels.”", "Help her push the wheelbarrow", "“Ask the Guild for more. You risk more than anyone.”"] },
      quien: { say: ["Nobody, say the foremen. It's the rock expanding with the heat.",
                     "My grandfather taught me to count knocks. These come two by two. Like the Hondura's when it's warning that someone was left below."] },
      parar: { say: ["Stop? With what it pays?",
                     "But she takes off her helmet. She wipes her hand across her face, black with dust.",
                     "My grandfather didn't dig for money. He dug so nobody would forget. I'll talk to the others. If the wall knocks two by two, someone is warning us. The Hondura will go to the Heart with that, not with wheelbarrows."] },
      empujar: { say: ["You push the wheelbarrow to the tunnel mouth. It weighs as if it were full of lead. When you reach the top your hands are hot, red.",
                       "Thanks. Now wash your hands well in cold water. Well. The ones who don't wash them, by next moon they don't close them the same."] },
      mas: { say: ["Galena goes to the Guild with other miners and asks for double. They give it without arguing.",
                   "Without arguing. That's what scares me. If they give you double without arguing, it's worth triple."] },
    } },

    "e4-veta": { who: { galena: "Galena, miner" }, nodes: {
      a: { say: ["In the deepest tunnel, Galena shows you a red vein running through the wall like a blood vessel. It glows. And it moves: very slowly, rising and falling, like a chest breathing.",
                 "It beats. Put your hand there. Don't touch the metal: put your hand near it.",
                 "You hold your hand a palm's width from the vein. You feel the heat. And a rhythm, slow, deep: one, pause, one, pause. Like the heart of something very large that sleeps."],
           opts: ["“It's the Root. This is part of the Root.”", "Draw a map of the vein", "Seal the tunnel", "Sing the lullaby to the vein"] },
      raiz: { say: ["The Root? We're taking pieces of the Root? To make a bell that puts it to sleep?",
                    "She stares at the full wheelbarrow.",
                    "It's like drawing someone's blood to make them a sleeping draught. And they fall asleep because you drew their blood."] },
      mapa: { say: ["You follow the vein with a lamp for hours. It runs down and to the north. Towards the Heart.",
                    "All the veins run the same way. If this is what I think, the Bell is being made from the very thing it's going to put to sleep."] },
      sellar: { say: ["You block the tunnel with stones and mortar. Galena knocks twice on the sealed wall, in farewell.",
                      "From the other side, far off, very slowly, two knocks answer.",
                      "There. Let nobody dig here. I'll write it in the Hondura's book. In big letters."] },
      nana: { say: ["You sing the lullaby softly, close to the vein. The rhythm slows. The glow dims, like an ember covering itself with ash.",
                    "It's falling asleep. With the lullaby it falls asleep on its own. It doesn't need a bell. It needs someone to sing to it.",
                    "When you stop singing, the glow comes back, slowly. But slower than before."] },
    } },
  });

  add("heights", {
    "e4-peaje": { who: { peaje: "Peaje, carter" }, nodes: {
      a: { say: ["Up the northern pass climbs a line of carts with ingots under tarpaulins. The wheels leave two smoking lines in the snow. A Heights carter, his face burned by cold and heat at once, guides the oxen.",
                 "Root metal for outside. Beyond the mountains they pay what nobody here would. They say they make swords from it that never chip.",
                 "The Heights always carried things from one side to the other. Messages, verses, water. Now we carry this. What weighs, pays."],
           opts: ["“Does the Guild know it's sold outside?”", "“Let the Heights not take the metal out of the Glade.”", "“Charge a toll, and let it go to the workers.”", "Help him over the pass"] },
      sabe: { say: ["The Guild sells it. We carry it. The Houses buy it here and resell it there. Everyone knows. Nobody says.",
                    "What leaves the Glade doesn't come back, the old folk say. But the coins come back. Those always do."] },
      quedar: { say: ["And what do the Heights live on? Wind?",
                      "He looks at the smoke lines in the snow. At the valley below, where the Crater's smoke can be seen.",
                      "All right. This trip is the last. Heights carts take no more metal from under the Glade. Let others take it, if they want, but not over our passes. That's what we'll say in the Heart."] },
      cobrar: { say: ["Peaje raises a barrier on the pass and charges a coin per ingot. He sends the coins in a bag, every moon, to the Crater, for the workers with grey hands.",
                      "It isn't much. But the metal that leaves pays something of what it costs to dig. Before, it paid nothing."] },
      cruzar: { say: ["You help push the carts up the steepest part. The snow melts under the wheels and the mud comes up to your ankles.",
                      "Thanks. On the other side nobody knows where the Ford is. But they'll use metal that passed through your hands."] },
    } },

    "e4-alud": { who: { peaje: "Peaje, carter" }, nodes: {
      a: { say: ["In the high-slope village, below the pass, people look at the mountain in fear. The hot carts melted the snow lower down. The snow above is left hanging, enormous, with nothing to hold it.",
                 "If it falls, it takes the village. Thirty houses. The old folk won't leave. They say the mountain hasn't fallen in a thousand years.",
                 "The mountain hasn't had hot carts going over it in a thousand years either, I tell them."],
           opts: ["Help get the people out of the village", "Bring the snow down early, carefully, with everyone far away", "“Let the carts stop until it snows again.”"] },
      sacar: { say: ["You spend the day carrying old folk, goats and boxes. By nightfall, the village is empty. Two old women refuse to leave. You leave them blankets and a candle.",
                     "The snow doesn't fall that night. Nor the next. On the third, it falls. The two old women got out at the last moment. Of the village, only the roofs are left.",
                     "Thirty houses. All for a metal going outside."] },
      caer: { say: ["With everyone far away, Peaje and the carters throw stones from one side until the snow breaks loose. It falls with a noise heard all the way to the Crater.",
                    "It takes half the village. The other half is left standing. Nobody dies.",
                    "Half. Well. The old folk will hate me all my life. But they'll be alive to hate me."] },
      parar: { say: ["Stop the carts? Until winter?",
                     "He talks to the other carters. They argue at the top of their voices. In the end, the line of carts waits in the valley, the ingots smoking under the tarpaulins.",
                     "Two weeks later it snows. The new snow holds up the old. The village is saved whole. The Guild gets its ingots fifteen days late, and Fogarín says nothing."] },
    } },
  });

  add("deep", {
    "e4-deshielo": { who: { tempano: "Témpano, ice keeper", fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["In the White Deep, things drip. The ice roofs drip, the walls, the icicles over the doors. It's a sound nobody here had ever heard. An old keeper puts buckets under the leaks.",
                 "The ice is melting. For the first time. My grandmother said the Deep's ice was eternal. That the Root made it to keep something.",
                 "Now the heat comes from below. From the Guild's furnaces, dug under everything. The Deep never had to defend itself from fire. We don't know how."],
           opts: ["“What did the ice keep?”", "“Go to the Guild and demand they close the furnaces under the Deep.”", "Help her move people to the high caves", "Gather the meltwater and keep it"] },
      guardaba: { say: ["Nobody knows. The stories say the cold. That the Root kept all the Glade's cold here for when it was needed.",
                        "If it melts, where does the cold go? Is it lost? Or does it all come back at once, some day?"] },
      exigir: { say: ["Témpano goes down to the Crater with four Deep keepers, wrapped in furs, in the full heat. Fogarín receives them sweating.",
                      "Closing the furnaces under the Deep means delaying the Bell a year.",
                      "Not closing them means the Deep stops existing. Choose which year you'd rather lose.",
                      "Fogarín closes two of the five furnaces. Témpano goes back without a word of thanks. The White Deep will go to the Heart, she says, to tell what happens when fire doesn't ask."] },
      mudar: { say: ["You help take the old and the children to the high caves, where the ice doesn't drip yet. It takes a week.",
                     "We're moving upwards. As if we were fleeing the ground. The White Deep climbing. My grandmother would die of shame."] },
      guardar: { say: ["You gather the water from the leaks in wooden barrels. It's clear water, very cold, that doesn't warm even if you leave it in the sun.",
                       "Kept cold. If the ice goes, at least let this remain. Some day someone will need it."] },
    } },

    "e4-aguanegra": { who: { tempano: "Témpano, ice keeper" }, nodes: {
      a: { say: ["Where the Deep's oldest ice melted, the ice under the hall of the Watch, black water appears. It isn't water: it's thick, it glistens, and it smells of something you've known for a long time.",
                 "Sap. Black sap, the old kind. It was frozen down here, for I don't know how many eras. The ice held it still.",
                 "Now it's moving. Slowly. South, towards the Heart. As if something were calling it."],
           opts: ["Gather it in barrels before it gets far", "Freeze it again with the kept cold water", "Follow it to see where it goes", "“Warn every people.”"] },
      juntar: { say: ["You spend two days filling barrels with wooden shovels. The sap sticks to everything. Your arms are black to the elbows.",
                      "On the third day, Cobre turns up with two carts and a purse. He wants to buy the barrels. He says the Houses remember what sap was worth.",
                      "I won't sell it to him. But now he knows it exists. And if he knows, everyone knows."] },
      congelar: { say: ["You pour over the sap the cold water you kept from the thaw. Where it falls, the sap goes hard, dull, still.",
                        "It works. Old cold serves for old things. But there's no cold water left. If it melts again, there's nothing to do it with."] },
      seguir: { say: ["You follow the black thread under the ice for hours. It runs down through cracks, under a river, into the rock. Always south.",
                      "At last it joins another thread, red, coming from the Crater. The two go into the earth together, towards the Heart.",
                      "The old sap and the new metal go to the same place. I don't know what it means. I don't like it."] },
      avisar: { say: ["You send warnings with everyone who passes. In a week, the news is in every people: there's black sap in the White Deep.",
                      "Some are afraid. Many remember the stories. A few start asking what it's worth.",
                      "Warning is right. But warnings are heard by those who shouldn't hear them too."] },
    } },
  });

  add("heart", {
    "e4-campana": { who: { fogarin: "Fogarín, Master of the Guild", retama: "Retama, keeper of the Stump" }, nodes: {
      a: { say: ["In the Heart, beside the third statue, a small bell hangs from a wooden scaffold, the size of a bucket, of a red that never goes out. It's the first test one. The big one is still being cast.",
                 "This one already works. We tried it last night. It rings, and for an hour, all over the Heart, the Root doesn't move. Not a tremor.",
                 "I'm Retama. I've kept the Stump since old Brezo died. And I'm telling you: that hour wasn't sleep. It was something else. The creatures didn't go near the Stump all night.",
                 "The Houses want to take it to the Meadow, for the turns. I don't know who to give it to. You decide. You're the one person nobody has ever bought anything from."],
           opts: ["“What did the Root feel when it rang?”", "Give it to the Houses", "Take it to the Ford", "“Let nobody have it. Let it stay here, unrung.”"] },
      sintio: { say: ["I don't know what the Root feels. Nobody does. But the Stump's roots went cold as stone. And the flowers around it closed at midnight, as if it were day.",
                      "Because it slept. That's what sleeping is.",
                      "That's going quiet. It's not the same."] },
      casas: { say: ["The small bell goes down to the Meadow in a House cart. Cobre receives it with shaking hands.",
                     "Well. That's it. They paid. Maybe that's fair.",
                     "Now the Root sleeps when a House pays. Let someone remember this day."] },
      vado: { say: ["You carry the small bell to the Ford, wrapped in a blanket. It weighs as if you were carrying a sleeping child.",
                    "You hang it at the entrance, away from the creatures. Nobody touches it. Your creature looks at it every morning from a distance, ears down.",
                    "At the Ford. Where nothing is sold. All right. Let whoever looks after things ring it, if it's ever needed."] },
      nadie: { say: ["Unrung? All that forging for nothing?",
                     "Retama ties the bell's tongue with a rag and a rope. The bell is left hanging from the scaffold, mute, beside the smith's statue.",
                     "Not for nothing. So it can be seen that it could be done, and that the choice was not to. That has to be forged too.",
                     "Fogarín leaves without saying goodbye. That night he's seen sitting at the foot of the third statue, his hand on the slag."] },
    } },

    "e4-final": { who: { fogarin: "Fogarín, Master of the Guild", escoria: "Escoria, worker", retama: "Retama, keeper of the Stump" }, nodes: {
      a: { say: ["The Hot Root falls, and the Heart's ground stays warm, like a kitchen floor. Above, on the scaffold, hangs the big Bell, finished. It's red and never goes out.",
                 "It's ready. One note and the Root sleeps forever. Nobody else has to go down to the deep furnaces, because no more metal is needed. Nobody else turns to stone.",
                 "And nobody sings to it any more. And nobody knows what happens to something that sleeps like that, with nobody singing to it, forever.",
                 "There's something else that can be done. Put out the furnaces. All of them. Not for one night: forever. Let Fire stop drinking altogether."],
           opts: ["“What happens if I ring the Bell?”", "“And if we put out every furnace?”", "“And if no one person decides?”", "Ring the Bell", "Put out every furnace in the Glade", "Share out the metal: one small forge per people, with all nine as witnesses"] },
      q1: { say: ["The Root sleeps. Deeply. No more tremors, no more sap, no more thirst. The deep furnaces close because they're no longer needed.",
                  "And the Root hears nothing any more. No lullabies, no footsteps, nothing. Something deaf asleep beneath everything. I don't know what that is, but it isn't peace."] },
      q2: { say: ["The stone hands end. The root metal ends. The Guild ends too. And us.",
                  "Fire doesn't know how to do anything but burn. With no furnaces, Fire goes down to the Ford to beg. All my life I saw Fire bought. Now I'd see it begging."] },
      q3: { say: ["The metal gets shared out. One small forge per people. No deep ones. Each people draws little, and pays little.",
                  "And the thirst gets shared. A little everywhere. The Root cools on every side at once. That only works if all nine say yes. If one's missing, that one builds its deep forge, and it all comes back."] },
      campana: { say: ["You climb the scaffold. Fogarín hands you the mallet. It weighs as if it were made of stone.",
                       "You strike. The note is so deep it can't be heard: it's felt in the bones, in the teeth, in the ground. It goes down to the bottom. Below, something enormous stops moving.",
                       "There. There. Nobody else.",
                       "Listen. You can't hear anything now. Not even the Heart's birds.",
                       "That night it starts to snow. It's early for snow. Nobody thinks much of it."] },
      ascuas: { say: ["You go down to the Crater with Escoria and Retama. Furnace by furnace, they go out. The workers help. Some cry. Some smash their shovels on the ground.",
                      "The deep furnaces don't go out with water. They're stopped with stones, with earth, with whatever there is. It takes a whole week.",
                      "There. Not one more hand of stone. And no work either. Tomorrow I'm going to the Ford to see if anyone needs firewood. Me, who had four hundred workers behind me.",
                      "The Bell stays hanging in the Heart. Cold. Mute. It's the greatest thing I made in my life, and it's a statue."] },
      forja: { say: ["The nine arrive. Each brings something: Escoria's strike, the Wood's resin, the Court's charcoal, the Tides' paper, the Hondura's book, the Heights' closed passes, the Deep's claim, the Night of Embers, the turn the Houses gave away.",
                     "Fogarín melts down the big Bell. The red metal is shared into nine ingots. Each people takes one for a small forge. No deep ones. No furnace going down further than an arm.",
                     "Little forge. Little metal. Few stone hands. Little of everything.",
                     "And little thirst. Everywhere. The Root neither sleeps nor wakes: it cools, slowly, on every side at once. I don't know if that's good. It belongs to everyone."] },
    } },
  });
  /* ==================== Delivery 2: the Day (Dawn Meadow, Warm Crater, Deep Forest) ==================== */

  /* ---------- Dawn Meadow: the board of nights, the ground that opens and the auction ---------- */
  add("aurora", {
    "e4-tablero": { who: { cerillo: "Cerillo" }, nodes: {
      a: { say: ["In front of the board of Bell turns, a barefoot boy from the Quarter counts the squares with his finger. His lips move. He gets it wrong and starts again.",
                 "Three hundred and sixty-five. And not one has a door without a lantern. Well, one does, but they painted it not long ago.",
                 "My grandmother says the Root used to sleep when someone sang to it. Now it sleeps when someone pays. How much is one night? So I know how much I have to save."],
           opts: ["“What do you want a night for?”", "Tell him the real price", "Teach him the lullaby, which costs nothing", "Draw a square with him, in chalk, without paying"] },
      para: { say: ["So the Root sleeps on my sister's birthday. That night the Quarter always shakes. The cups fall. She cries.",
                    "One still night. That's all. So nothing falls."] },
      precio: { say: ["You tell him what the House of Cobre paid for eight nights. Cerillo works it out in the dust with a stick.",
                      "Two hundred years of collecting tins. Fine. Now I know.",
                      "He rubs out the sum with his foot. He doesn't cry. He keeps looking at the board a while longer, the way you look at a shop window."] },
      nana: { say: ["You sit with him on the edge of the fountain and sing him the lullaby, slowly, twice. Cerillo repeats it, off-key.",
                    "And this makes it sleep? Without paying?",
                    "You tell him it used to. That you don't know if it's enough now. Cerillo shrugs.",
                    "I'll sing it that night anyway. If it doesn't work, at least my sister falls asleep."] },
      tiza: { say: ["You pick up a piece of chalk from the ground. On the edge of the board, outside the squares, Cerillo draws one more: a night that isn't in the year, with a cup standing in the middle.",
                    "The next day there are ten chalk squares. The day after, forty. The Houses send people to rub them out. They come back.",
                    "They don't do anything. I know. But now everyone sees nights are missing."] },
    } },

    "e4-badajo": { who: { badajo: "Badajo, bell-ringer of the Houses" }, nodes: {
      a: { say: ["In the courtyard of a House, a young man strikes a wooden bell with a leather-wrapped mallet. It makes no sound. He strikes again. He counts out loud.",
                 "They're teaching me to ring the Bell. The Houses want their own ringer for when they bring it. I practise on wood because the real one, the test one, deafens whoever rings it up close.",
                 "I can't hear well in this ear anymore. Not much in the other either. They say it's the wood. It isn't the wood: they made me ring the real one once, to see if I could take it."],
           opts: ["“What does it feel like when it rings?”", "“Stop practising. They're buying your ears.”", "“Practise with earplugs. Ask them to give you some.”", "Strike the wooden bell yourself"] },
      siente: { say: ["You don't hear it. You feel it in your teeth. And then a huge silence, as if someone had shut a door the size of the Meadow.",
                      "The pigeons left the courtyard that afternoon. They never came back."] },
      dejar: { say: ["And what do I do? My father was a lamplighter. When the lanterns went out, he sat at the door for ten years. I don't want to sit at the door.",
                     "But he leans the mallet against the wall.",
                     "No practice today. Today I listen. While I can still hear something."] },
      tapones: { say: ["Badajo goes to ask the House for earplugs. They give him beeswax and a pat on the back.",
                       "It works. A little. At least now I know my ears are worth something to someone. To you."] },
      golpear: { say: ["You take the mallet and strike the wood. It makes no sound. But your creature, on the ground, puts its paws over its ears, as if it had heard something you didn't.",
                       "It hears it. See? The wood rings too. For them it does."] },
    } },

    "e4-ambar": { who: { ambar: "Lady Ámbar" }, nodes: {
      a: { say: ["In a big Meadow house with bare walls, an old woman sits on the only chair left. Where paintings used to hang there are lighter marks on the paint. She is Cobre's mother.",
                 "I sold it all. The paintings, the rugs, the lantern at the entrance, the one from the Vigil. So my son can buy nights from a bell that doesn't ring yet.",
                 "My grandmother sold light. I sell what my grandmother bought with the light. In the end, Caretaker, the Houses only know how to sell. And buy. And call it tradition."],
           opts: ["“Do you agree with the Bell?”", "“Cobre painted a night for the Quarter.”", "“Your House could stop buying.”", "Ask her about the Vigil lantern"] },
      acuerdo: { say: ["I agree with my son eating. The Bell is the last thing that can be bought in the Glade. If we don't buy it, the Court will.",
                       "And if the Court has the nights, the Meadow ground opens when they want. That already happened. In another era, with another thing. It always happens."] },
      barrio: { say: ["Yes. He told me. He thought I'd die of the shock.",
                      "She laughs, quietly, without much heart.",
                      "It was the only thing he ever did in his life without asking me. That day I thought maybe my House doesn't end with him. Maybe something else begins."] },
      dejar: { say: ["Stop buying? And keep what?",
                     "She looks at the empty walls. The marks of the paintings.",
                     "You're right about one thing. There's nothing left to lose. That gives you a horrible kind of freedom. I'll talk to my son. I won't tell him what to do. I'll tell him he doesn't need to save me anymore."] },
      farol: { say: ["I sold it to the Guild. They melted it down. It was root glass, from when the Houses drew light from the wells.",
                     "Now it's part of the Bell, I suppose. My grandmother's light, made into a bell to put to sleep the Root that woke. Some things find their own way back to where they started."] },
    } },

    "e4-candela": { who: { candela: "Grandma Candela" }, nodes: {
      a: { say: ["On a corner of the Quarter, an old woman sells bread from a window. Her hands are covered in flour and her eyes are still quick. You recognise her by the way she counts coins in her palm: it's Candela, Aurelia's granddaughter.",
                 "Caretaker. It's Candela, remember? Still alive. Me too, look. Both things are strange.",
                 "My grandson works in the deep furnaces. His nails are grey. He tells me it's soot. I saw my grandmother say she knew nothing with the face of someone who knew everything. I know that face."],
           opts: ["“You read the notebook aloud, at the Trial.”", "“You drank a cup every moon, to see if your grandmother would open it.”", "“You defended your grandmother on every corner.”", "“What do you want to do about your grandson?”", "“Tell him about the statue in the Heart.”"] },
      leyo: { say: ["I read it and left. I left the surname on the stage. I've sold bread ever since. Nobody asks me which House I'm from.",
                    "My grandson doesn't know he's an Albor. Better. A surname is a debt they leave you."] },
      bebia: { say: ["Until the lake dried up. She never opened it. After death, same as before.",
                     "Now I see my grandson doing the same with his hands. Looking at them and not opening them. That gets passed down."] },
      defendia: { say: ["I shouted a lot. I don't shout anymore. My voice got tired before my anger did.",
                        "Grandmother knew. I knew too. That's why I shouted."] },
      nieto: { say: ["That he leave the furnaces. He doesn't listen. He says the Guild pays and I sell bread.",
                     "He's right. But bread doesn't turn you to stone."] },
      estatua: { say: ["You tell her about the third statue: the slag stuck to its base, just like on the workers' hands.",
                       "Candela closes the bread window. She shakes the flour off her hands.",
                       "My grandmother kept quiet and it cost the whole Quarter. I won't keep quiet. I'll tell my grandson, and every grandchild on this street. Let the Meadow know the Quarter knows things too."] },
    } },

    "e4-hundimiento": { who: { cerillo: "Cerillo" }, nodes: {
      a: { say: ["At dawn, on the edge of the Meadow, a house is missing. Where it stood there is a round, deep hole, its rim still smoking. Down below, a red glow.",
                 "Last night was a Court night on the board. The Root didn't sleep. The ground opened. The family got out through the window. The house didn't.",
                 "Around the hole, people from the Houses measure with ropes. Someone from the Court watches from afar, veil on. From the bottom of the hole come blows: someone is digging."],
           opts: ["“Who's digging down there?”", "Help the family that lost the house", "Go down into the hole", "Confront the one from the Court"] },
      quien: { say: ["Guild miners. They went down as soon as it opened. They say there are good veins under the Meadow houses.",
                     "On Court nights the ground opens, and the Guild digs. Nobody bought a night so the house wouldn't fall."] },
      familia: { say: ["You spend the day with the family: a mother, two kids and a grandfather who doesn't speak. You find them blankets, a roof at the Ford for a few nights, soup.",
                       "You didn't give them back the house. But you gave them a place that doesn't shake. That's a lot."] },
      bajar: { say: ["You climb down a rope. Down there it's as hot as a furnace. Three miners pick at a red vein that climbs the wall like a root.",
                     "One looks at you and pulls the cloth from his mouth. He has a young face and hands grey up to the wrist.",
                     "He says nothing. He goes back to digging. Up above, through the hole, there's a piece of sky in the shape of a house."] },
      corte: { say: ["You walk up to the one from the Court. She lifts her veil. A young woman, with dark circles under her eyes.",
                     "You tell her the night was theirs. That the house fell on their night.",
                     "She doesn't deny it. She gives you a coin, the only one in her hand, for the family.",
                     "“We bought the night so the ground would open under the Dawn Tower,” she says. “We didn't know where it would open. Nobody knows where it opens.”"] },
    } },

    "e4-subasta": { who: { cobre: "Cobre, of the Houses", badajo: "Badajo, bell-ringer of the Houses" }, nodes: {
      a: { say: ["In the Meadow square there's a stage and an auctioneer with a gavel. Up for auction is the first stroke of the great Bell, the night they hang it: whoever wins decides whether it rings or not.",
                 "The Houses pooled everything. Everything. The Court too. They're neck and neck. If we win, Badajo rings. If the Court wins, it doesn't ring, and that night the ground opens under the whole Meadow.",
                 "I don't know if I want to ring it. But if I do, at least I know where the ground won't open."],
           opts: ["“And if nobody wins?”", "Bid for the Ford", "Let the Court win", "Climb onto the stage and stop the auction"] },
      ninguno: { say: ["Then the stroke stays free. And the Guild decides. And the Guild sells the stroke to whoever pays most afterwards. So someone wins anyway."] },
      vado: { say: ["You raise your hand. The whole square turns to look at you. The auctioneer repeats your bid, which is small, and nobody understands it.",
                    "The Houses and the Court look at each other. Neither bids again. Both would rather the Ford have it than the other.",
                    "The Ford won. With nothing. Because nobody wanted the other side to win. That's how you win in the Glade.",
                    "Then I'm not ringing it. Fine. I'm a little glad."] },
      corte: { say: ["You do nothing. The bidding climbs. In the end the Court wins by one coin. The grey veils applaud in silence.",
                     "We lost. My House lost. That night the ground will open wherever the Court wants.",
                     "Badajo leaves the wooden mallet on the stage and walks off. He looks relieved, though he tries not to show it."] },
      parar: { say: ["You climb onto the stage. The auctioneer stares at you, gavel in the air. You speak loudly: the Root isn't for auction, the ground that opens doesn't choose an owner, the house that fell belonged to someone who bought nothing.",
                     "Some applaud. Many shout. The auctioneer lowers the gavel without striking.",
                     "You ruined it. Everything we saved. Well. You ruined it for the Court too.",
                     "The auction doesn't happen. The stroke stays in the hands of the Guild, which doesn't know what to do with it."] },
    } },

    "e4-escuela": { who: { pizarra: "Pizarra, teacher" }, nodes: {
      a: { say: ["In a Meadow school, twenty kids sitting on the floor recite the history of the Glade from memory. A teacher with chalk in her hair listens with her eyes closed.",
                 "Come in, Caretaker. The kids learn what happened. What the Chronicle says, at least. Now it's the Bell's turn: that the Guild will put the Root to sleep forever, and that this is progress.",
                 "The little ones ask me who used to sing to the Root. I don't know what to tell them. Do you?"],
           opts: ["“The Chronicle blames the Court. It's not the whole truth.”", "“The Houses paid for the blame by selling the forges.”", "“Nobody remembers the Line anymore. I do.”", "Tell the kids who used to sing", "Teach them the lullaby"] },
      farol: { say: ["I know. My grandmother was from the Court. I teach the Chronicle because otherwise they'd throw me out.",
                     "But to the Court kids I say, quietly, that their grandmother wasn't the only one. They look at me as if I'd given them a present."] },
      mareas: { say: ["Yes. And the Houses' kids know it. Some carry it like a shame, others like a war wound.",
                      "None of them knows that what they sold is what the Bell is made of now. That's in no book."] },
      espejo: { say: ["The Line? What Line?",
                      "You explain. She writes on the board while you talk, fast, so she won't forget.",
                      "This isn't written anywhere. Nobody knows it. If it's true, the Bell is a huge mistake. And nobody will see it coming."] },
      contar: { say: ["You tell the kids: that the Root used to sleep with a lullaby, that all the peoples had to come together to sing it, that it was hard and that's why it was worth it.",
                      "A little girl raises her hand. “So why don't we sing it now, instead of making a bell?”",
                      "Nobody answers. Pizarra writes the question on the board, in big letters, and doesn't erase it at the end of class.",
                      "Tomorrow I'll ask the Houses. The question is hers. I'm just carrying it."] },
      nana: { say: ["You sing the lullaby. The kids learn it in three rounds. In the end they sing it by themselves, off-key, loud.",
                    "Outside, in the street, someone passing by stops to listen. Then another.",
                    "It's not in the curriculum. But I'll sing it again tomorrow, in case they forget."] },
    } },
  });

  /* ---------- Warm Crater: the young masters, the casting, Chispa, Escoria and Tizón ---------- */
  add("crater", {
    "e4-maestros": { who: { fogarin: "Fogarín, Master of the Guild", fuelle: "Fuelle, young master" }, nodes: {
      a: { say: ["In the Guild masters' hall there's a long table with twelve chairs. Fogarín sits at the head. At the other end, a young master with strong arms and already grey nails bangs the table with his fist.",
                 "More deep furnaces! With ten more, the great Bell is done in a year. And with what's left over, we make tools the Glade has never seen!",
                 "With ten more, in a year we have four hundred more stone hands. Fuelle, look at your nails.",
                 "My nails are mine, Master. And the Guild belongs to those who work, not to those who remember the Tides."],
           opts: ["“Why the hurry, Fuelle?”", "Back Fogarín", "Back Fuelle", "“Let the workers vote, not the masters.”"] },
      prisa: { say: ["Because if we don't finish it, the Houses will, with our furnaces. Or the Court with its charcoal. The Bell has to belong to Fire.",
                     "All our lives they bought from us. For once, let them buy something from us that only we know how to make."] },
      fogarin: { say: ["You speak in favour of Fogarín. The old masters nod. The young ones eye you with distrust.",
                       "They vote: no new furnaces. Fuelle gets up and leaves, slamming the door.",
                       "Thank you. That boy will be Master someday. I hope with hands."] },
      fuelle: { say: ["You speak in favour of Fuelle. Fogarín looks at you with something close to sadness.",
                      "They vote: five new furnaces, not ten. Fuelle smiles as if he'd won everything.",
                      "Five. Fine. Five more furnaces is what Fire takes when nobody tells it no. Remember this day, Caretaker."] },
      votar: { say: ["The workers? The ones sitting on the floor with their arms crossed?",
                     "The ones who have the hands. Yes. Let them vote.",
                     "That afternoon four hundred workers vote in the Guild courtyard, with white and black stones in a bucket. Black wins: no new furnaces. Fuelle counts the stones twice.",
                     "Fine. I lost to my own people. That hurts differently."] },
    } },

    "e4-fundicion": { who: { yunque: "Yunque, smith" }, nodes: {
      a: { say: ["It's casting day. The root metal runs down the stone channel towards the enormous mould of the great Bell, red, slow, like a river that thinks. A hundred workers watch in silence.",
                 "Halfway along, the channel cracks. The metal starts spilling out one side, towards where the youngest workers stand. Yunque is closer than anyone.",
                 "Back! Everyone back!"],
           opts: ["Help Yunque plug the crack", "Get the young ones out of there", "Sing the lullaby to the metal"] },
      tapar: { say: ["You run with Yunque. He pushes his grey hand into the crack, the stone one, the one that no longer feels. The metal doesn't burn it. You shove a slab against the channel wall.",
                     "The crack closes. The metal flows on to the mould. Yunque pulls his hand out. Now the stone reaches his elbow.",
                     "It doesn't hurt. I told you. It just weighs more."] },
      jovenes: { say: ["You push the young workers back, shouting. The metal passes where they were and cools in a red puddle on the ground.",
                       "Yunque plugs the crack by himself, with his stone hand. When he's done, he looks at it the way you look at a broken tool.",
                       "Well done. They still have flesh hands. May they last."] },
      nana: { say: ["You don't know why you do it. You sing. The metal spilling from the crack grows slower, darker, as if it were listening.",
                    "Yunque takes the chance and plugs the crack. The rest of the metal reaches the mould unhurried.",
                    "What was that? The metal went still. Like an animal when you talk to it softly.",
                    "The workers look at you strangely for the rest of the day. Some hum the lullaby under their breath as they work."] },
    } },

    "e4-chispa2": { who: { chispa: "Chispa" }, nodes: {
      a: { say: ["On the south slope, behind her house, Chispa has built a forge from river stones and a bellows made from a leather bag. She's hammering something tiny.",
                 "Caretaker! Look. It's a nail. My first nail. It's crooked, but it's a nail.",
                 "She shows you her hand. The little grey spot on her fingertip has grown. Now it covers the whole nail."],
           opts: ["“What metal did you make it with?”", "“Tizón taught you to forge cold.”", "“I gave you that hammer.”", "Take her to dip her hand in Forest resin", "“Keep going. You're doing well.”"] },
      metal: { say: ["River iron, mostly. And a tiny bit of red. From an ingot that fell off a cart. Just a tiny bit, so it holds.",
                     "With the tiny bit of red the iron gets good. It bends and doesn't break. Don't tell anyone."] },
      frio: { say: ["Yes. It's boring. It takes three times as long. But the master says whoever forges cold still has hands at a hundred. Like him.",
                    "I made this nail cold. Nothing red. That's why it's crooked. But it's all mine."] },
      martillo: { say: ["Yes! I use it every day. It already has a dent in the shape of my hand.",
                        "When I grow up, I'm going to make you one. Better than this."] },
      resina: { say: ["You take her to the Forest. Hacha lets her dip her hand in a bucket of resin from an old tree.",
                      "When she pulls it out, the nail is still grey. But the fingertip bends again.",
                      "It moves. It moves! Okay. I won't use red anymore. I swear. At least until I grow up."] },
      sigue: { say: ["Really? For real?",
                     "She starts hammering harder, happy. The little grey spot glints a bit in the fire.",
                     "You leave. From the slope you can still hear the hammer, small, stubborn."] },
    } },

    "e4-escoria": { who: { escoria: "Escoria, worker" }, nodes: {
      a: { say: ["Escoria sits on the Guild steps, alone, hands in her lap. She doesn't shout anymore. Her voice is hoarse from doing it so much.",
                 "Come to see how it ended? Sit down."],
           opts: ["“The deep furnaces closed because of the strike.”", "“Half went back to work for Cobre's purse.”", "“The short-shift deal was signed.”", "“And your hands?”"] },
      huelga: { say: ["They closed for a week. Then the Guild brought people from outside, from the south slope, people who didn't know. Now the kids from the slope have grey hands, and we have no work.",
                      "We won. That's how you win: you pass the problem to someone poorer."] },
      recado: { say: ["Half. Now half have a purse and grey hands. The other half, nothing. And both sides hate me: some for not taking the purse, others for making them feel it was wrong to take it.",
                      "Cobre sent me a letter asking for forgiveness. I used it to light the fire."] },
      mediar: { say: ["One-hour shifts. It works. Hands go grey more slowly. More slowly isn't never.",
                      "But look: last week someone broke a foreman's hand because he made him stay two hours. Before, nothing got broken. Now there's a paper to break."] },
      manos: { say: ["Escoria raises her hands. They're grey up to the wrist. The fingers bend, but slowly, as if they think before moving.",
                     "Still. But not for long. When I can't move them anymore, I want someone to remember why. I don't want a statue. I want them to remember."],
               opts: ["“I'll remember.”", "“Write it down. Let the Hollow keep it in stone.”", "“Go to the Heart. Let the nine peoples see it.”"] },
      acordar: { say: ["You. Well. You remember things from sixty years ago. That's what they say.",
                       "She takes your hand in hers, hard and warm. She doesn't squeeze. She can't squeeze much."] },
      escribir: { say: ["Escoria dictates. You write. The names of the grey-handed workers, the shifts, the hours, what happened with the strike.",
                        "Galena takes it to the Caves and carves it on a new wall, far from the others. A wall of hands.",
                        "There. In stone. Which is what's going to happen to all of us. At least let it say who we were."] },
      corazon: { say: ["To the Heart? To beg?",
                       "She stares at her hands for a long while.",
                       "Not to beg. To show. If the nine peoples come together, the Quarter will go with these hands raised. So nobody can say they didn't know."] },
    } },

    "e4-tizon": { who: { tizon: "Master Tizón" }, nodes: {
      a: { say: ["Master Tizón is in bed. There's a pile of coins on the blanket, sorted by size. He breathes slowly, with a whistle. When he sees you, he smiles with half his mouth.",
                 "You came. Good. I'm dying. Don't make that face: I'm a hundred and twelve and I counted these coins twice every day of my life. It was about time.",
                 "I don't know who to leave them to. The Guild, which was my life. Or someone who isn't Guild. You decide. I've decided too much already."],
           opts: ["“Why did you count them twice?”", "“Leave them to the Guild.”", "“Leave them to Chispa.”", "“Leave them to the grey-handed workers.”"] },
      dos: { say: ["Because the first time you count what you have. The second, what it cost you to have it.",
                   "It never came out the same. Not once in a hundred years."] },
      gremio: { say: ["The Guild. Yes. Let it outlive me. It's the only thing I ever wanted.",
                      "He closes his eyes. Fogarín arrives that night and sits beside the bed until morning. He doesn't count the coins."] },
      chispa: { say: ["The girl from the slope. Yes. The one who forges cold because I asked her to.",
                      "He gives you the coins wrapped in a rag. They weigh more than they look.",
                      "Tell her not to count them. Or to count them once. Don't let her learn my habit. Let her learn the other one.",
                      "He dies at dawn. Chispa receives the rag and cries for an hour without opening it."] },
      obreros: { say: ["Tizón looks at you for a long time. Then he nods, slowly.",
                       "All my life I paid them what was fair. Fair by my count. Let them keep it. For resin, for food, for whatever they lack when they can't close their fists anymore.",
                       "He dies that night. The coins are handed out in the Guild courtyard, one per worker. Escoria counts hers twice and laughs, crying."] },
    } },
  });

  /* ---------- Deep Forest: the Council, the clearing, the last old tree and the fire ---------- */
  add("forest", {
    "e4-musgo": { who: { musgo: "Musgo, of the Council" }, nodes: {
      a: { say: ["In the Council house, seven elders argue about whether they're allowed to argue. A man with a greenish beard presides from a chair of roots. Every so often someone says “no” and everyone nods.",
                 "The Council banned logging. A year ago. The woodcutters keep logging. The Council banned selling wood to the Guild. They keep selling. The Council banned talking about this. And here we are.",
                 "We know how to say no. It's the only thing we know. We don't know what to do when nobody listens to the no."],
           opts: ["“Stop banning and pay for looking after it.”", "“Talk to Hacha. She plants three for one.”", "“Ban it harder. Post guards.”", "“What did the Council say before it learned to say no?”"] },
      pagar: { say: ["Pay? The Council has no coins. It has moss, mushrooms and years.",
                     "One of the elders raises a hand. He says they have seeds. The oldest in the Glade. Worth more than wood, if someone knows how to use them.",
                     "Seeds for trees left standing. It's an idea. A strange idea. It's not a no. It's been a long time since the Council had an idea that wasn't a no."] },
      hacha: { say: ["The woodcutter? The one who cuts?",
                     "You tell them about the three for one. The seven elders look at each other.",
                     "Then the one who cuts cares for it more than the Council. I don't like that. But it's true. Let Hacha come to the next session. With her axe, if she wants. The Forest will go to the Heart with the one who cuts and the one who doesn't."] },
      guardias: { say: ["The Council sends twelve young people with sticks to guard the old trees. Within a week, six have gone over to the woodcutters. The Guild pays them more.",
                        "You see. A no with a stick is a no that can be bought."] },
      antes: { say: ["Before it learned to say no... it said “wait”. That's what the records say. “Wait for it to grow.” “Wait and see.”",
                     "I think some old Council got tired of waiting, and learned the no. Faster. Worse."] },
    } },

    "e4-claro": { who: {}, nodes: {
      a: { say: ["Where there used to be a dense forest, there's now a huge clearing full of stumps. The sun pours straight in. It's hot. The moss on the stones has dried and falls off in pieces.",
                 "No birds can be heard. The Forest creatures have gone deeper in, where there's still shade. Your creature presses against your legs, eyes squinting in the light.",
                 "At the edge of the clearing, a tiny Forest creature, alone, circles a stump. It's looking for something that's no longer there."],
           opts: ["Go up to the creature by the stump", "Plant something in the clearing", "Keep going towards the shade"] },
      criatura: { say: ["You crouch. The creature looks at you and doesn't run. In the stump there's a hollow, and in the hollow, the remains of a nest.",
                        "Your creature approaches slowly and touches its nose with its own. The two stay still a while.",
                        "In the end the tiny creature follows you to the shade, a few steps behind, coming no closer. That night it sleeps near the campfire."] },
      plantar: { say: ["With your hands you dig a hole in the dry earth and bury a seed you'd been carrying in your pocket since who knows when. You water it from your canteen.",
                       "It won't grow. It's too hot, the soil is full of ash. You know it. You plant it anyway.",
                       "Your creature sits beside the hole. When you leave, it stays a while longer, as if waiting for something."] },
      seguir: { say: ["You cross the clearing quickly, without looking. In the shade on the other side the air is cool, and smells of leaves. A bird can be heard, far off.",
                      "Behind you, the clearing shines like an empty plate."] },
    } },

    "e4-carboneros": { who: { hacha: "Hacha, woodcutter", hulla: "Hulla, Court charcoal burner" }, nodes: {
      a: { say: ["At the border between the Forest and the Hollow, two groups glare at each other. On one side, woodcutters with axes. On the other, Court people with veils and black shovels.",
                 "The Court sells charcoal to the Guild cheaper than our wood. If they keep it up, we're out of work. And the Forest gets cut anyway, because the Court cuts too: here, at night, and burns it in the Hollow.",
                 "We cut what you leave lying around. Branches, stumps. Whole trees, you cut those. Don't come saying the Forest is yours because you kill it first."],
           opts: ["“Why fight each other and not the Guild?”", "Propose they work together: wood and charcoal, one price", "Take Hacha's side", "Take Hulla's side"] },
      gremio: { say: ["Because you can't hit the Guild. It's far away, it has furnaces, it pays.",
                      "And each other, we can. It's always easier to fight someone who's as stuck as you are.",
                      "They look at each other. For a moment, they almost laugh."] },
      juntos: { say: ["You propose a deal: one price for wood and charcoal, paid by the Guild equally to both. And that neither cuts living trees over a hundred years old.",
                      "With the Court? My grandmother would rise from her grave.",
                      "Mine too. Maybe they'll meet on the way and come to an agreement.",
                      "They sign with earth on their fingers, on a stone. The price reaches the Guild the next day. Fogarín accepts it without haggling. He says it was about time someone agreed on something."] },
      hacha: { say: ["You side with the woodcutters. The Court backs away, slowly, towards the Hollow.",
                     "Fine. Now we know whose side the Ford is on. Always the side with more people.",
                     "That night three axes vanish from Hacha's camp. Nobody saw anything."] },
      hulla: { say: ["You side with the Court. The woodcutters glare at you.",
                     "The Court. Of course. The one that always has an excuse. Enjoy the charcoal.",
                     "The next day the Guild stops buying wood. It only buys charcoal. Twelve woodcutter families go without income that month."] },
    } },

    "e4-retono": { who: { retono: "Retoño, of the Council" }, nodes: {
      a: { say: ["On the shore of the Forest lake, a grey-haired man with a stainless mouth sits on a small chair someone brought out of the Council house. He's looking at the stumps on the far shore.",
                 "Caretaker. It's Retoño. Years have passed. I was the boy with the purple mouth, remember? Now the mouth is clean and the Forest is cut. I don't know which is worse.",
                 "The Forest's young people don't go to the lake to drink visions anymore. They go to the Crater to work. They come back with grey hands. There's always something the young go looking for outside, and it always costs them something."],
           opts: ["“You speak for the young in the Council.”", "“You stayed on the shore counting the ones who came back.”", "“You went down to the shore with the Council elders.”", "“What would it take for them to stay?”", "“Go to the Crater and bring them back.”"] },
      concejo: { say: ["I speak. The second thing I was going to ask for, I never said. I don't remember what it was anymore. I think it was “that you can come back”.",
                       "Now I'd ask for it. That you can come back from the Crater with your hands whole."] },
      orilla: { say: ["I used to count them. Now I count the ones who come back from the Crater. More of them come back. But they come back different.",
                      "The small chair is still empty in the Council. I took it out to look at the water. Nobody claimed it."] },
      viejos: { say: ["We'd go down. We'd talk until the sun came up. Now the elders of back then are dead and the elders of now are us.",
                      "Tomorrow I'm going down with the young ones from the Crater. Let's see if talking fixes something. It didn't fix anything before. But we got to know each other."] },
      quedar: { say: ["Work. Something that pays and doesn't turn you to stone or take your memories. The Forest never paid for being looked after. That's the same old problem.",
                      "If the Council paid with seeds, with land, with something... The young don't want coins. They want something of their own."] },
      traer: { say: ["Retoño gets up from the small chair slowly. He leaves for the Crater that same afternoon, on foot.",
                     "He comes back a week later with eight young people from the Forest. Their nails are grey. One, the whole hand.",
                     "Eight out of forty. The others said no. That the Guild pays and the Forest doesn't. They're right. But these eight are going to plant the three for one. It's something."] },
    } },

    "e4-semillas": { who: { hacha: "Hacha, woodcutter" }, nodes: {
      a: { say: ["In the clearing of stumps there are rows of planted saplings. Hundreds of them, with little sticks beside them so they don't fall over. Half are yellow. Some, black at the tip.",
                 "The soil is full of furnace ash. And hot from below. The saplings can't take it. We plant three for one and two die.",
                 "An old tree takes three hundred years. A sapling dies in a month. The numbers don't add up, Caretaker. They never did."],
           opts: ["“Why is the ground hot?”", "Water them with the cold water from the Deep", "Plant in the shade, further in", "“Plant anyway. Some will hold.”"] },
      caliente: { say: ["The veins. The miners say there are red veins running under the Forest, towards the Heart. They heat everything from below.",
                        "The Forest is cooking from the bottom up. And we're planting on top."] },
      fria: { say: ["Témpano sends two barrels of cold meltwater. They water a whole row of saplings.",
                    "A week later, that row is green. The others aren't.",
                    "The cold of the Deep saves the Forest. But only one row. And the cold water doesn't come back. That's how it always is: enough for one row."] },
      sombra: { say: ["They transplant the remaining saplings further in, into the shade of the trees still standing. It takes days.",
                      "They last longer there. But there the old trees steal their light. As always. The old don't let the new grow, and if you cut them, the new ones cook."] },
      igual: { say: ["Plant anyway. Yes. That's what my grandmother did. She planted even when she knew.",
                     "They keep planting. By the end of the season, of a hundred saplings eleven remain. Hacha counts them the way you count children."] },
    } },

    "e4-arbolviejo": { who: { hacha: "Hacha, woodcutter", musgo: "Musgo, of the Council", escoria: "Escoria, worker" }, nodes: {
      a: { say: ["At the centre of the Forest stands one enormous tree, the oldest, the one the Council calls the Mother. Around it are three people who aren't speaking to each other.",
                 "Its resin alone is enough for a hundred workers for a year. A hundred pairs of hands that bend again.",
                 "Its wood is enough for the Guild to stop buying firewood for three winters. Twelve families eat for three years.",
                 "And it's the Mother. The seeds of the whole Forest come from her. If they cut her, the Forest doesn't come back. Ever."],
           opts: ["“Is there no other way to get resin from it?”", "“Cut it. Hands first.”", "“Bleed it little by little, without cutting it.”", "“Nobody touches it.”"] },
      otra: { say: ["Bleed it. Make small cuts in the bark and collect what drips. It takes years. It weakens her. But she lives.",
                    "Years. My hands don't have years."] },
      cortar: { say: ["It takes two days to cut her down. She falls with a sound heard all the way to the Meadow. The Forest goes silent.",
                      "The resin goes in barrels to the Crater. A hundred workers dip their hands. They come out soft. Escoria cries in front of everyone.",
                      "There. The Mother heals hands. Let them remember that when the Forest doesn't come back."] },
      sangrar: { say: ["They make twelve small cuts in the bark, like open veins. The resin drips slowly into buckets. One bucket a moon.",
                       "One bucket a moon. Twelve hands a moon. Fine. Twelve is more than none.",
                       "And the Mother is still standing. Wounded, but standing. Like everyone here."] },
      nadie: { say: ["Nobody? You're going to look at my hands when they don't move anymore and tell me it was worth it for a tree?",
                     "You have no answer that would help her. Musgo puts his hand on the Mother's bark.",
                     "Thank you. The Forest won't forget it. Neither will Escoria. Both things are true."] },
    } },

    "e4-incendio": { who: { hacha: "Hacha, woodcutter" }, nodes: {
      a: { say: ["At dusk smoke rises from the edge of the Forest, where the metal carts' road runs. An ingot fell from a cart and set the dry leaf litter alight. The fire is moving towards the new saplings.",
                 "Water! Earth! Anything!",
                 "The woodcutters run with buckets. It isn't enough. The fire is red, too red, and water won't put it out: the ingot in the middle keeps burning."],
           opts: ["Dig a trench to cut off the fire", "Pull the ingot out of the middle of the fire", "Save the saplings, even if the rest burns"] },
      zanja: { say: ["With the woodcutters you dig a wide trench between the fire and the old Forest. It takes all night. The fire reaches the trench and stops.",
                     "On the other side everything is black: the saplings, the stumps, the road. The old Forest, on this side, untouched.",
                     "We saved the old. The new burned. It's always like that when you have to choose fast."] },
      lingote: { say: ["You cover yourself with a wet blanket and go in. The heat is so strong you can't breathe. You grab the ingot with two green branches and drag it to the stream.",
                       "When it falls in the water, the stream boils and gives off a red steam. Without the ingot, the fire weakens. The buckets are enough.",
                       "Have you lost your mind? Well. Thank you. Look at your hands.",
                       "Your palms are red. And on one, a little grey spot the size of a lentil."] },
      brotes: { say: ["You run to the saplings with the youngest woodcutters. They pull up what they can, soil and all, and carry them to the stream in their arms.",
                      "They save forty. The rest of the clearing burns. The fire reaches the edge of the old Forest and burns three trees before they stop it.",
                      "Forty saplings for three old trees. I don't know if it's a good trade. But we chose the saplings."] },
    } },
  });

})(window.EVEVENTS_EN);
